class Solution {public long solve(String text){char[] open=new char[text.length()];long[] inside=new long[text.length()];int depth=0;long total=0;for(char c:text.toCharArray()){if(c=='('||c=='['||c=='{'){open[depth]=c;inside[depth++]=0;}else{if(depth==0)return -1;char o=open[depth-1],expected=o=='('?')':o=='['?']':'}';if(c!=expected)return -1;long child=inside[--depth],value=child==0?(o=='('?1:o=='['?2:3):2*child;if(depth>0)inside[depth-1]+=value;else total+=value;}}return depth==0?total:-1;}}